<script setup lang="ts">
import { computed, ref } from 'vue'
import AppIcon from '../components/AppIcon.vue'
import { actualDark, discardPreferences, palettes, preferenceDirty, preferences, savePreferences, storageMessage, type ThemeMode } from '../lib/preferences'
const saveError = ref('')
const connectionError = computed(() => { try { const url = new URL(preferences.endpoint); return ['http:', 'https:'].includes(url.protocol) ? '' : '服务地址须采用 http 或 https' } catch { return '请输入完整服务地址，如 http://127.0.0.1:8517' } })
function save() { saveError.value = connectionError.value; if (!saveError.value) savePreferences() }
function discard() { saveError.value = ''; discardPreferences() }
</script>
<template><div class="settings-page"><section class="panel appearance-panel"><div class="panel-heading"><div><h2>外观设置</h2><p class="hint">修改后可预览，保存后下次启动生效。</p></div><AppIcon name="palette" :size="22" /></div><div class="settings-row"><div><h3>明暗模式</h3><p class="hint">当前使用{{ actualDark ? '夜间' : '日间' }}外观</p></div><div class="segmented mode-tabs"><button v-for="mode in [{ id: 'light', label: '日间', icon: 'sun' }, { id: 'dark', label: '夜间', icon: 'moon' }, { id: 'system', label: '跟随系统', icon: 'monitor' }]" :key="mode.id" :class="{ selected: preferences.mode === mode.id }" :aria-pressed="preferences.mode === mode.id" @click="preferences.mode = mode.id as ThemeMode"><AppIcon :name="mode.icon" :size="15" />{{ mode.label }}</button></div></div><div class="settings-section-title"><h3>工作台主题</h3><p class="hint">选择主题配色。</p></div><div class="theme-cards"><button v-for="palette in palettes" :key="palette.id" :class="['theme-card', { selected: preferences.palette === palette.id }]" :aria-pressed="preferences.palette === palette.id" :aria-label="`${palette.label}主题预览`" @click="preferences.palette = palette.id"><span class="theme-previews"><span v-for="mode in ['light','dark']" :key="mode" :class="['mini-preview', mode]" :style="{ '--preview-accent': mode === 'dark' ? palette.dark : palette.color }"><span class="mini-sidebar"><i /><i /><i /></span><span class="mini-workspace"><span class="mini-heading" /><span class="mini-chart"><svg viewBox="0 0 100 38" fill="none" aria-hidden="true"><path d="M0 10H100M0 24H100" stroke="currentColor" opacity=".12" /><path d="M0 34h9l3-12 4 12h13l4-29 4 28h11l4-17 4 17h17l4-23 4 23h15" stroke="var(--preview-accent)" stroke-width="1.5" stroke-linejoin="round" /></svg></span><span class="mini-bottom"><i /><i /></span></span></span></span><span class="theme-card-label">{{ palette.label }}<AppIcon v-if="preferences.palette === palette.id" name="check" :size="15" /></span></button></div><div class="settings-row motion-row"><div><h3>减少动态</h3><p class="hint">减少非必要动画，并遵循系统偏好。</p></div><label class="switch"><span class="sr-only">减少动态</span><input v-model="preferences.reducedMotion" type="checkbox" aria-label="减少动态" /><span class="switch-track" /></label></div></section>
  <div class="settings-grid"><section class="panel settings-section"><div class="panel-heading"><h2>连接配置</h2><span class="badge neutral">未连接</span></div><p class="hint">配置仅保存在本地，尚未连接引擎。</p><label class="field">服务地址<input v-model="preferences.endpoint" type="text" placeholder="http://127.0.0.1:8517" /></label><p v-if="connectionError" class="error-text">{{ connectionError }}</p><div class="connection-status"><span>NIST 数据源</span><b>未连接</b></div><div class="connection-status"><span>计算服务</span><b>未连接</b></div><div class="backend-action"><button class="btn" disabled>连接 / 检测服务</button><span class="hint">本阶段未接入</span></div></section><section class="panel settings-section"><div class="panel-heading"><h2>运行环境</h2><span class="badge neutral">未检测</span></div><p class="hint">路径仅保存在本地。</p><label class="field">Python 可执行文件路径<input v-model="preferences.pythonPath" type="text" placeholder="尚未配置" /></label><label class="field">浏览器驱动路径<input v-model="preferences.driverPath" type="text" placeholder="尚未配置" /></label><div class="connection-status"><span>Python / 浏览器驱动</span><b>未检测</b></div><div class="backend-action"><button class="btn" disabled>检测运行环境</button><span class="hint">连接引擎后可用</span></div></section></div>
  <div class="settings-savebar"><span v-if="preferenceDirty" class="hint">有未保存更改</span><span v-else class="hint">设置已保存</span><div><button class="btn" :disabled="!preferenceDirty" @click="discard">放弃更改</button><button class="btn primary" :disabled="!preferenceDirty || !!connectionError" @click="save"><AppIcon name="save" :size="15" />保存设置</button></div></div><p v-if="saveError" class="error-text" role="alert">{{ saveError }}</p><p v-if="storageMessage" class="settings-message" role="status">{{ storageMessage }}</p>
</div></template>
